Let $\pi$ be a cuspidal automorphic representation of $\mathrm{U}(V_K)(\mathbb A_K)$, consider the period integral
\begin{equation}
  \mathcal P(f,\phi) = \int_{[\mathrm{U}(V)]}
         f(h)\overline{\Theta(h,\phi)}\, dh  
\end{equation}
for $f \in \pi$, $\phi \in \mathcal S(\mathbb L(\mathbb A))$. Here $[\mathrm{U}(V)]=\mathrm{U}(V)(F) \backslash \mathrm{U}(V)(\mathbb A)$.

We say a cuspidal automorphic representation $\Pi$ of $\mathrm{GL}_n(\mathbb A_L)$ is \emph{Hermitian} if
\begin{itemize}
    \item $\Pi$ is conjugate self dual (i.e. $\Pi^\vee \cong \Pi^c$, where $\Pi^c$ is defined by $\Pi^c(g)=\Pi(g^c)$).
    \item The Asai $L$-function $L(s,\Pi,\operatorname{As}_{L/K}^{(-1)^{n+1}})$ has a pole at $s=1$.
\end{itemize}

Consider the action of a group $T$ on a set $\widetilde{S}$. Let $S \subseteq \widetilde{S}$ be a subset, and $H=\mathrm{Stab}(S) \leq T$. Assume that
\begin{enumerate}
    \item For any $\widetilde{y} \in \widetilde{S}$, there exists $y \in S$ and $g \in T$ such that $g\widetilde{y}=y$.
    \item If $gy_1=y_2$ for some $g \in T$ and $y_1, y_2 \in S$, then there exists $h \in H$ such that $hy_1=y_2$.
\end{enumerate}
Then the natural inclusion $H \backslash S \to G \backslash \widetilde{S}$ is a bijection.

We also have 
\[
    g^{-1}\delta g 
    = \gamma\gamma'^{-1}
    (\gamma'\sigma_{L/E}(\gamma')^{-1}) \gamma'\gamma^{-1}
    = \gamma (\sigma_{L/E}(\gamma')^{-1}\gamma')
    \gamma^{-1}
    = \delta.
\]

We say that an element of $\mathrm{Mat}_n(L) \times L_n \times L^n$ is 
\emph{strongly regular semisimple} if and only if
\begin{enumerate}
    \item $\xi$ is regular semisimple as an element
    of $\mathrm{Mat}_n(L)$;
    \item the vectors $\{x, x\xi, \dots, x\xi^{n-1}\}$ 
    span the $L$-vector space $L_n$;
    \item the vectors $\{y, \xi y, \dots, \xi^{n-1} y\}$
    span the $L$-vector space $L^n$.
\end{enumerate}

Note that $\sigma_{L/E}(\varsigma^\ast) = \varsigma$ then implies
\begin{align*}
    \sigma_{L/E}(\zeta^\ast) = \sigma_{L/M}(c_{n-1}) \varsigma^{n-1}
    + \cdots + \sigma_{L/M}(c_0) = h^{-1}\sigma_{L/M}(\gamma) h.
\end{align*}
This implies $\zeta^\ast = h^{-1}\sigma_{L/K}(\gamma) h$,
so $\zeta\zeta^\ast = 1$ since
$\gamma\sigma_{L/K}(\gamma) = 1$.

For $f \in C_c^\infty(G(\mathbb A))$ and
$\phi_1 \otimes \phi_2 \in 
\mathcal S(\mathbb L(\mathbb A))^{\otimes 2}$, 
consider the relative trace formula distribution
\begin{equation}
    J(f, \phi_1 \otimes \phi_2)
    = \int_{[H]}\int_{[H]}
    K_f(h_1, h_2) \overline{\Theta(h_1, \phi_1)}
    \Theta(h_2, \phi_2)\,dh_1\,dh_2.
\end{equation}
Here $K_f(x, y)=\sum_{\gamma \in G(F)} f(x^{-1}\gamma y)$ is the automorphic kernel function.

J(f, \phi_1 \otimes \phi_2)
    = \int_{[H]}\int_{[H]}
    K_f(h_1, h_2) \overline{\Theta(h_1, \phi_1)}
    \Theta(h_2, \phi_2)\,dh_1\,dh_2.

We have
\begin{align*}
    &\sum_{\zeta \in G(F)}
    f(h_1^{-1}\zeta h_2)\overline{\Theta(h_1, \phi_1)}\Theta(h_2, \phi_2) \\
    &\overset{\mathrm{Def.} \ref{def:ugood} (2)}{=} \sum_{\zeta \in R }
    \sum_{(a, b) \in T_\zeta \backslash (H\times H)(F)} 
    f(h_1^{-1}a^{-1}\zeta b h_2) \overline{\Theta(h_1, \phi_1)} \Theta(h_2, \phi_2)  \\
    &\overset{\mathrm{Thm.} \ref{key:reduction}}{=} \sum_{\zeta \in R }
    \sum_{(a, b) \in T_\zeta \backslash (H\times H)(F)} 
    f(h_1^{-1}a^{-1}\zeta b h_2)
    \sum_{z \in V^\vee(E)}( \overline{\omega((bh_2)^{-1}ah_1)\phi_1} \otimes \phi_2 )^\ddagger(zbh_2)\\
    &= \sum_{\zeta \in R} 
    \sum_{(a, b)\in T_\zeta \backslash (H \times H)(F)}    f(h_1^{-1}a^{-1}\zeta bh_2) 
    \sum_{z \in T_\zeta(F) \backslash V(F)}\sum_{t \in T_{[\zeta, z]} \backslash T_\zeta}
    ( \overline{\omega (h^{-1}_2b^{-1}ah_1)\phi_1} \otimes \phi_2)^\ddagger(ztbh_2) \\
    &=\sum_{[\zeta, z] \in [Y_{\textnormal{rss}}]}
    \sum_{(a, b) \in (H\times H)(F)}
    f(h_1^{-1}a^{-1}\zeta bh_2)
    ( \overline{\omega(h^{-1}_2b^{-1}ah_1)\phi_1} \otimes \phi_2)^\ddagger(zbh_2),
\end{align*}
Thus,
\begin{align*}
    J(f, \phi_1 \otimes \phi_2)= \sum_{[\zeta, z] \in [Y_{\textnormal{rss}}]}
    \int_{H(\mathbb A)}\int_{H(\mathbb A)}
    f(h_1^{-1}\zeta h_2)
    (\overline{\omega(h^{-1}_2h_1)\phi_1} \otimes \phi_2)^\ddagger(zh_2)\,dh_1\,dh_2.
\end{align*}
Both sides converge because of Definition 
\ref{def:ugood}\eqref{ursssupp} .

We have
\begin{align*}
    &\sum_{\zeta \in G(F)}
    f(h_1^{-1}\zeta h_2)\overline{\Theta(h_1, \phi_1)}\Theta(h_2, \phi_2) \\
    &\overset{\mathrm{Def.} \ref{def:ugood} (2)}{=} \sum_{\zeta \in R }
    \sum_{(a, b) \in T_\zeta \backslash (H\times H)(F)} 
    f(h_1^{-1}a^{-1}\zeta b h_2) \overline{\Theta(h_1, \phi_1)} \Theta(h_2, \phi_2)  \\
    &\overset{\mathrm{Thm.} \ref{key:reduction}}{=} \sum_{\zeta \in R }
    \sum_{(a, b) \in T_\zeta \backslash (H\times H)(F)} 
    f(h_1^{-1}a^{-1}\zeta b h_2)
    \sum_{z \in V^\vee(E)}( \overline{\omega((bh_2)^{-1}ah_1)\phi_1} \otimes \phi_2 )^\ddagger(zbh_2)\\
    &= \sum_{\zeta \in R} 
    \sum_{(a, b)\in T_\zeta \backslash (H \times H)(F)}    f(h_1^{-1}a^{-1}\zeta bh_2) 
    \sum_{z \in T_\zeta(F) \backslash V(F)}\sum_{t \in T_{[\zeta, z]} \backslash T_\zeta}
    ( \overline{\omega (h^{-1}_2b^{-1}ah_1)\phi_1} \otimes \phi_2)^\ddagger(ztbh_2) \\
    &=\sum_{[\zeta, z] \in [Y_{\textnormal{rss}}]}
    \sum_{(a, b) \in (H\times H)(F)}
    f(h_1^{-1}a^{-1}\zeta bh_2)
    ( \overline{\omega(h^{-1}_2b^{-1}ah_1)\phi_1} \otimes \phi_2)^\ddagger(zbh_2),
\end{align*}

Thus,
\begin{align*}
    J(f, \phi_1 \otimes \phi_2)= \sum_{[\zeta, z] \in [Y_{\textnormal{rss}}]}
    \int_{H(\mathbb A)}\int_{H(\mathbb A)}
    f(h_1^{-1}\zeta h_2)
    (\overline{\omega(h^{-1}_2h_1)\phi_1} \otimes \phi_2)^\ddagger(zh_2)\,dh_1\,dh_2.
\end{align*}

Let $R_\mu$ be the Weil representation of $H_1(\mathbb A_F)=\mathrm{GL}_n(\mathbb A_E)$, realized on $\mathcal S(\mathbb A_{E,n})$ by
\begin{equation}
   (R_\mu(g)\phi')(z) = \mu(\det g) \lvert \det g \rvert^{\frac12}
    \phi'(zg). 
\end{equation}    
For $\phi' \in \mathcal S(\mathbb A_{E,n})$,
define the theta series by   
\begin{equation}
\Theta_\mu(s, g, \phi') = \sum_{z \in E_n \setminus \{0\}} (R_\mu(g) \phi')(z) \lvert \det g \rvert^{s-\frac 12}
\end{equation}
for $g \in \mathrm{GL}_n(\mathbb A_E)$, and let 
$\Theta_\mu(g, \phi') = \Theta_\mu(\frac12, g, \phi')$.

For $[\xi, x, y] \in G'(F) \times F_n \times F^{-,n}$,
$f_v' \in C_c^\infty(G'(F_v))$ with $\xi\sigma_{L/K}(\xi)^{-1} \in S$, and $\phi_v' \in \mathcal S(E_{v,n})$,
define the \emph{(local) orbital integral}
\begin{equation}
    \mathrm{Orb}([\xi, x, y], f_v', \phi_v'):= \int_{H_1(F_v)}\int_{H_2(F_v)}
        f_v'(h_1^{-1}\xi h_2) 
        \overline{(R_{\mu_v}(h_1) \phi_v')^\dagger(x, y)}
        \eta_{L_v/K_v}(h_2)^{n+1}\, dh_1 \, dh_2.
\end{equation}

\mathrm{Orb}([\xi, x, y], f_v', \phi_v'):= \int_{H_1(F_v)}\int_{H_2(F_v)}
        f_v'(h_1^{-1}\xi h_2) 
        \overline{(R_{\mu_v}(h_1) \phi_v')^\dagger(x, y)}
        \eta_{L_v/K_v}(h_2)^{n+1}\, dh_1 \, dh_2.

First note that
\begin{align*}
    &\int\limits_{\mathrm{GL}_n(K) \backslash \mathrm{GL}_n(\mathbb A_K)}
    \sum_{\xi \in \mathrm{GL}_n(L)}
    f'(g^{-1}\xi h) \eta_{L/K}(h)^{n+1}\,dh\\ 
    &= \int\limits_{\mathrm{GL}_n(K)\backslash \mathrm{GL}_n(\mathbb A_K)}
    \sum_{\xi \in \mathrm{GL}_n(L)/\mathrm{GL}_n(K)}
    \sum_{a \in \mathrm{GL}_n(K)} f'(g^{-1}\xi a h)
    \eta_{L/K}(ah)^{n+1}\, dh \\
    &= \sum_{\xi \in \mathrm{GL}_n(L)/\mathrm{GL}_n(K)}
    \int_{\mathrm{GL}_n(\mathbb A_K)} f'(g^{-1}\xi h)\eta_{L/K}(h)^{n+1}\, dh\\
    &= \sum_{\gamma \in \textnormal{S}_n(K)}
    \int_{\mathrm{GL}_n(\mathbb A_K)} f'(g^{-1}\xi h)\eta_{L/K}(h)^{n+1}\, dh,
\end{align*}
where in the last sum, $\xi \in \mathrm{GL}_n(L)$ such that $\gamma = \xi\xi^{\sigma, -1}$,
and the integral does not depend on the choice of
$\xi$.
Then
\begin{align*}
    &\sum_{\gamma \in \textnormal{S}_n(K)}
    \int_{\mathrm{GL}_n(\mathbb A_K)} f'(g^{-1}\xi h)\eta_{L/K}(h)^{n+1}
    \overline{\Theta_\mu(g, \phi')} \, dh \\
    &= \sum_{\gamma \in S} \sum_{a \in T_\gamma \backslash \mathrm{GL}_n(E)}
    \int_{\mathrm{GL}_n(\mathbb A_K)}
    f'(g^{-1}a^{-1}\xi h) \eta_{L/K}(h)^{n+1}
    \overline{\Theta_\mu(ag, \phi')} \, dh\\
    &= \sum_{\gamma \in S} \sum_{a \in T_\gamma\backslash \mathrm{GL}_n(E)}
    \int_{\mathrm{GL}_n(\mathbb A_K)}
    f'(g^{-1}a^{-1}\xi h)\eta_{L/K}(h)^{n+1}\sum_{[x, y] \in F_n \times F^{-,n}}
    \overline{(R_\mu(ag)\phi')^\dagger(x, y)} \, dh\\
    &= \sum_{\gamma \in S} \sum_{a \in T_\gamma \backslash \mathrm{GL}_n(E)}
    \int_{\mathrm{GL}_n(\mathbb A_K)} f'(g^{-1}a^{-1}\xi h)
    \eta_{L/K}(h)^{n+1}\\
    &\hspace{15em}\times \sum_{[x, y] \in (F_n \times F^{-,n})/T_\gamma} 
    \sum_{t \in T_{[\gamma, x, y]} \backslash T_\gamma}
    \overline{(R_\mu(tag)\phi')^\dagger(x, y)}\, dh \\
    &= \sum_{[\gamma, x, y] \in [X_{\textnormal{rss}}]}
    \sum_{a \in \mathrm{GL}_n(E)} 
    \int_{\mathrm{GL}_n(\mathbb A_K)}
    f'(g^{-1}a^{-1}\xi h) \eta_{L/K}(h)^{n+1}
    \overline{(R_\mu(ag)\phi')^\dagger(x, y)}\, dh,
\end{align*}
where $T_{[\gamma, x, y]}$ denotes the
stabilizer of $[x, y]$ in $T_\gamma$.
Combining the above calculations gives
\begin{align*}
    I(f', \phi') &= 
    \sum_{[\gamma, x, y] \in [X_{\textnormal{rss}}]}
    \int_{\mathrm{GL}_n(\mathbb A_E)}
    \int_{\mathrm{GL}_n(\mathbb A_K)} 
    f'(g^{-1}\xi h) \overline{(R_\mu(g)\phi')^\dagger(x, y)}\eta_{L/K}(h)^{n+1}\,dh\, dg. \qedhere
\end{align*}

First note that
\begin{align*}
    &\int\limits_{\mathrm{GL}_n(K) \backslash \mathrm{GL}_n(\mathbb A_K)}
    \sum_{\xi \in \mathrm{GL}_n(L)}
    f'(g^{-1}\xi h) \eta_{L/K}(h)^{n+1}\,dh\\ 
    &= \int\limits_{\mathrm{GL}_n(K)\backslash \mathrm{GL}_n(\mathbb A_K)}
    \sum_{\xi \in \mathrm{GL}_n(L)/\mathrm{GL}_n(K)}
    \sum_{a \in \mathrm{GL}_n(K)} f'(g^{-1}\xi a h)
    \eta_{L/K}(ah)^{n+1}\, dh \\
    &= \sum_{\xi \in \mathrm{GL}_n(L)/\mathrm{GL}_n(K)}
    \int_{\mathrm{GL}_n(\mathbb A_K)} f'(g^{-1}\xi h)\eta_{L/K}(h)^{n+1}\, dh\\
    &= \sum_{\gamma \in \textnormal{S}_n(K)}
    \int_{\mathrm{GL}_n(\mathbb A_K)} f'(g^{-1}\xi h)\eta_{L/K}(h)^{n+1}\, dh,
\end{align*}
where in the last sum, $\xi \in \mathrm{GL}_n(L)$ such that $\gamma = \xi\xi^{\sigma, -1}$,
and the integral does not depend on the choice of
$\xi$.

Then
\begin{align*}
    &\sum_{\gamma \in \textnormal{S}_n(K)}
    \int_{\mathrm{GL}_n(\mathbb A_K)} f'(g^{-1}\xi h)\eta_{L/K}(h)^{n+1}
    \overline{\Theta_\mu(g, \phi')} \, dh \\
    &= \sum_{\gamma \in S} \sum_{a \in T_\gamma \backslash \mathrm{GL}_n(E)}
    \int_{\mathrm{GL}_n(\mathbb A_K)}
    f'(g^{-1}a^{-1}\xi h) \eta_{L/K}(h)^{n+1}
    \overline{\Theta_\mu(ag, \phi')} \, dh\\
    &= \sum_{\gamma \in S} \sum_{a \in T_\gamma\backslash \mathrm{GL}_n(E)}
    \int_{\mathrm{GL}_n(\mathbb A_K)}
    f'(g^{-1}a^{-1}\xi h)\eta_{L/K}(h)^{n+1}\sum_{[x, y] \in F_n \times F^{-,n}}
    \overline{(R_\mu(ag)\phi')^\dagger(x, y)} \, dh\\
    &= \sum_{\gamma \in S} \sum_{a \in T_\gamma \backslash \mathrm{GL}_n(E)}
    \int_{\mathrm{GL}_n(\mathbb A_K)} f'(g^{-1}a^{-1}\xi h)
    \eta_{L/K}(h)^{n+1}\\
    &\hspace{15em}\times \sum_{[x, y] \in (F_n \times F^{-,n})/T_\gamma} 
    \sum_{t \in T_{[\gamma, x, y]} \backslash T_\gamma}
    \overline{(R_\mu(tag)\phi')^\dagger(x, y)}\, dh \\
    &= \sum_{[\gamma, x, y] \in [X_{\textnormal{rss}}]}
    \sum_{a \in \mathrm{GL}_n(E)} 
    \int_{\mathrm{GL}_n(\mathbb A_K)}
    f'(g^{-1}a^{-1}\xi h) \eta_{L/K}(h)^{n+1}
    \overline{(R_\mu(ag)\phi')^\dagger(x, y)}\, dh,
\end{align*}
where $T_{[\gamma, x, y]}$ denotes the
stabilizer of $[x, y]$ in $T_\gamma$.

Combining the above calculations gives
\begin{align*}
    I(f', \phi') &= 
    \sum_{[\gamma, x, y] \in [X_{\textnormal{rss}}]}
    \int_{\mathrm{GL}_n(\mathbb A_E)}
    \int_{\mathrm{GL}_n(\mathbb A_K)} 
    f'(g^{-1}\xi h) \overline{(R_\mu(g)\phi')^\dagger(x, y)}\eta_{L/K}(h)^{n+1}\,dh\, dg. \qedhere
\end{align*}

For $[\delta, x, y] \in \textnormal{S}_{n, L/E} \times V^\vee \times V$,
define
\[
    T_{[\delta, x, y]} 
    = j_M^{n(n-1)/2} \cdot \det \begin{bmatrix}
        x \\ x\delta \\ \vdots \\ x\delta^{n-1}
    \end{bmatrix}.
\]

If $\gamma$ is normal, then $\delta \in \mathrm{GL}_n(M)$,
so it is easy to see that $\det(\xi\sigma_{L/M}(\xi))^{-(n-1)}T_{[\delta, x, y]}$
is also an element of $M$, so it is an element of $F$.
Thus, we may define
\begin{align*}
    \Omega([\xi, x, y]) &= \eta_{E/F}(\det(\xi\sigma_{L/M}(\xi))^{-(n-1)} 
    T_{[\delta, x, y]}).
\end{align*}

Suppose that $[\gamma, x, y] \in X_{\textnormal{rss}}$ and 
    $\gamma$ is Kottwitz.
    Suppose $\eta'$ is unramified. Then
    \begin{align*}
        &\mathrm{Orb}([\gamma, x, y], \widetilde f', \phi')\\
        &= 
        \int_{\mathrm{GL}_n(F)}
        \mathbf{1}_{\textnormal{S}_{n, \mathcal O_L/\mathcal O_K} \cap \textnormal{S}_{n, L/E}}
        (g^{-1}\gamma\sigma_{L/E}(\gamma)^{-1} g)
        (\phi')^\dagger(xg, g^{-1}y)\eta_{E/F}(g)\,dg.
    \end{align*}

Since $\phi'$ is fixed by $\mathrm{GL}_n(\mathcal O_E)$, we have
\begin{align*}
    \mathrm{Orb}([\gamma, x, y], \widetilde f', \phi')
    &= \int_{\mathrm{GL}_n(E)} \mathbf{1}_{\textnormal{S}_{n, \mathcal O_L/\mathcal O_K}}
    (g^{-1}\gamma \sigma_{E/F}(g)) \overline{(R_{\mu}(g)\phi')^\dagger(x, y)}
    \eta'(g)\, dg \\
    &= \int_{\mathrm{GL}_n(F)} \mathbf{1}_{\textnormal{S}_{n, \mathcal O_L/\mathcal O_K} \cap \textnormal{S}_{n, L/E}}
    (g^{-1} \gamma\sigma_{L/E}(\gamma)^{-1} g)
    \overline{(R_\mu(g)\phi')^\dagger(x, y)}\, dg \\
    &= \int_{\mathrm{GL}_n(F)} \mathbf{1}_{\textnormal{S}_{n, \mathcal O_L/\mathcal O_K} \cap
    \textnormal{S}_{n, L/E}}
    (g^{-1}\gamma\sigma_{L/E}(\gamma)^{-1} g)
    (\phi')^\dagger(xg, g^{-1} y) \eta_{E/F}(g) \,dg.
\end{align*}

Suppose that $[\zeta, z]^{V^+} \in Y_{\textnormal{rss}}^{V^+}$
    and $\zeta$ is Kottwitz. 
    Then
    \begin{align*}
        &\mathrm{Orb}([\zeta, z]^{V^+}, f, \phi_1 \otimes \phi_2)
        \\&= \int_{\mathrm{U}(V^+)(F)}
        \mathbf{1}_{\mathrm{U}(V^+)(\mathcal O_K) \cap \textnormal{S}_{n, L/E}}(h^{-1}
        \zeta\sigma_{L/E}(\zeta)^{-1} h)
        (\overline{\phi_1} \otimes \phi_2)^{\ddagger}(zh)\, dh.
    \end{align*}

Thus, since $\overline{\phi_1} \otimes \phi_2$ is fixed by 
$\mathrm{U}(V^+)(\mathcal O_F) \times \mathrm{U}(V^+)(\mathcal O_F)$,
we have
\begin{align*}
    \mathrm{Orb}([\zeta, z]^{V^+}, f, \phi_1 \otimes \phi_2) &= 
    \int_{\mathrm{U}(V^+)(F)} \mathbf{1}_{\mathrm{U}(V^+)(\mathcal O_K)}
    (h^{-1}\zeta h) 
    (\overline{\phi_1} \otimes \phi_2)^\ddagger(zh)\, dh \\
    &= \int_{\mathrm{U}(V^+)(F)} \mathbf{1}_{\mathrm{U}(V^+)(\mathcal O_K) \cap \textnormal{S}_{n, L/E}}
    (h^{-1} \zeta\sigma_{L/E}(\zeta)^{-1} h) 
    (\overline{\phi_1} \otimes \phi_2)^\ddagger(zh)\, dh.
    \qedhere
\end{align*}

Write $x \in F_n$, $y = (y_0, -y_0)$ for $y_0 \in F^n$.
By the same calculation as in the proof of \cite[Proposition~4.14]{TGGP-Wang}, we have 
\begin{align*}
    \overline{(R_\mu(g_1, g_2)\phi')^\dagger(x, y)}
    = (\overline{\omega(g_2^{-1}g_1, \prescript{\top}{}{}(g_1^{-1}g_2))\phi_1}
    \otimes \phi_2)^\ddagger((x, \prescript{\top}{}{} y_0)(g_2, \prescript{\top}{}{} g_2^{-1})),
\end{align*}
for any $g_1, g_2 \in \mathrm{GL}_n(F)$.
\begin{align*}
    &\mathrm{Orb}([\xi, x, y], f', \phi') \\
    &= \iint\limits_{\mathrm{GL}_n(F) \times \mathrm{GL}_n(F)} 
    \int\limits_{\mathrm{GL}_n(K)}
    f'((g_1^{-1}, g_2^{-1})(\xi_1, \xi_2)(h, h))
    \overline{(R_\mu(g_1, g_2)\phi')^\dagger(x, y)}\, dh \,dg_1\,dg_2 \\
    &= \iint\limits_{\mathrm{GL}_n(F) \times \mathrm{GL}_n(F)}
    \int\limits_{\mathrm{GL}_n(K)} f_1'(g^{-1}\xi_1\xi_2^{-1}g_2 h)f_2'(h)
    \overline{(R_\mu(g_1, g_2)\phi')^\dagger(x, y)}\, dh \,dg_1\,dg_2\\
    &= \iint\limits_{\mathrm{GL}_n(F) \times \mathrm{GL}_n(F)}
    f(g_1^{-1}\gamma_1 g_2)
    (\overline{\omega(g_2^{-1}g_1, \prescript{\top}{}{}(g_1^{-1}g_2))\phi_1} \otimes \phi_2)^\ddagger((x, \prescript{\top}{}{} y_0)(g_2, \prescript{\top}{}{} g_2^{-1})) \,dg_1\,dg_2.
\end{align*}

On the other hand,
let $z = (z_1, z_2) \in F_n \times F_n$.
Since $[\gamma, x, y]$ and $[\zeta, z]^V$, match,
there exists 
$h = (h_1, h_2) \in \mathrm{GL}_n(F) \times \mathrm{GL}_n(F)$
such that
\[
    [\gamma\sigma_{L/E}(\gamma)^{-1}, x, y].h
    = [\zeta\sigma_{L/E}(\zeta)^{-1}, z, z^\ast].
\]
Since $S$ and $R^V$ are compatible, we in fact have
\[
    [\gamma, x, y].h = [\zeta, z, z^\ast],
\]
which implies
\begin{equation} h_1^{-1}\gamma_1 h_1 = \zeta_1, \quad
    xh_1 = z_1, \quad \prescript{\top}{}{}{y_0}\prescript{\top}{}{}{h_1^{-1}} = z_2.
\end{equation}
Then the local obrital integral \eqref{defn: local orb: unitary side}
\begin{align*}
    &\mathrm{Orb}([\zeta, z], f, \phi_1 \otimes \phi_2) \\
    &= \iint\limits_{\mathrm{GL}_n(F) \times \mathrm{GL}_n(F)}
    f(g_1^{-1}\zeta_1 g_2)
    (\overline{\omega(g_2^{-1}g_1,
    \prescript{\top}{}{}(g_1^{-1}g_2))\phi_1} \otimes \phi_2)^\ddagger((z_1, z_2)(g_2,
    \prescript{\top}{}{} g_2^{-1}))\, dg_1\,dg_2
\end{align*}
is easily seen to be equal to our above expression
for $\mathrm{Orb}([\xi, x, y], f', \phi')$,
by \eqref{eq:changevar}.

Write $x \in F_n$, $y = (y_0, -y_0)$ for $y_0 \in F^n$.
By the same calculation as in the proof of \cite[Proposition~4.14]{TGGP-Wang}, we have 
\begin{align*}
    \overline{(R_\mu(g_1, g_2)\phi')^\dagger(x, y)}
    = (\overline{\omega(g_2^{-1}g_1, \prescript{\top}{}{}(g_1^{-1}g_2))\phi_1}
    \otimes \phi_2)^\ddagger((x, \prescript{\top}{}{} y_0)(g_2, \prescript{\top}{}{} g_2^{-1})),
\end{align*}
for any $g_1, g_2 \in \mathrm{GL}_n(F)$.
\begin{align*}
    &\mathrm{Orb}([\xi, x, y], f', \phi') \\
    &= \iint\limits_{\mathrm{GL}_n(F) \times \mathrm{GL}_n(F)} 
    \int\limits_{\mathrm{GL}_n(K)}
    f'((g_1^{-1}, g_2^{-1})(\xi_1, \xi_2)(h, h))
    \overline{(R_\mu(g_1, g_2)\phi')^\dagger(x, y)}\, dh \,dg_1\,dg_2 \\
    &= \iint\limits_{\mathrm{GL}_n(F) \times \mathrm{GL}_n(F)}
